insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('0c9cd1ce-001c-4bb1-8e93-d20062a8c7dc', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$inleiding: hardloper Brandon als proefpersoon$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context1.png$$,
   $$Brandon traint voor het lopen van halve marathons. Als student sportkunde is hij regelmatig proefpersoon voor allerlei metingen aan zijn lichaam (afbeelding 1).$$, 'inline'),
  ('6034fe7b-4ccf-4d3d-9223-f5a0fb647b4b', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$afbeelding 1: proefpersoon op een loopband$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context2.png$$,
   $$afbeelding 1: foto van een proefpersoon op een loopband met een onderzoeker$$, 'inline'),
  ('8543083c-9875-4820-8e6c-76117f7ea05b', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$kader: meetpil in de darmen en smartwatch (afbeelding 2)$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context3.png$$,
   $$Tijdens een halve marathon gebruikt Brandon een meetpil en een smartwatch om informatie te verzamelen over de werking van zijn lichaam. Hij heeft de meetpil voor de wedstrijd ingeslikt, zodat de pil zich tijdens de wedstrijd in zijn darmen bevindt. De meetpil (afbeelding 2) bevat een sensor die voortdurend de lichaamstemperatuur meet en doorgeeft aan de smartwatch. Tijdens de wedstrijd meet de smartwatch ook Brandons hartslag. Na de wedstrijd verlaat de meetpil het lichaam met de ontlasting.
afbeelding 2: foto van een meetpil tussen twee vingers$$, 'inline'),
  ('87cf9e01-af35-4388-94d3-b40690d21f81', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$zeven organen van het verteringsstelsel$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context4.png$$,
   $$Het verteringsstelsel bestaat uit onder andere de volgende organen:
1 alvleesklier
2 dikke darm
3 dunne darm
4 endeldarm
5 lever
6 maag
7 slokdarm$$, 'inline'),
  ('fdb729d2-7bbb-4cbd-8107-5e1e88010c74', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$meetresultaten tijdens het lopen zonder grootheden en eenheden$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context5.png$$,
   $$De meetresultaten tijdens het lopen zijn weergegeven in afbeelding 3. Op de assen ontbreekt de aanduiding van de grootheden en de eenheden.$$, 'inline'),
  ('3d640798-48ed-4818-8e04-b1b58ac3030e', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$afbeelding 3: meetresultaten tijdens het lopen$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context6.png$$,
   $$afbeelding 3: puntenwolk met trendlijn; x-as van 38,0 tot 40,0, y-as van 150 tot 180 (met asonderbreking vanaf 0). De punten stijgen van ongeveer 155 bij 38,4 tot ongeveer 176 bij 40,1. De grootheden en eenheden van de assen ontbreken.$$, 'inline'),
  ('b220f89b-9123-4bff-9df7-e8dfa6872018', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$verhit en zwetend over de finish$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context7.png$$,
   $$Na 1 uur en 25 minuten passeert Brandon verhit en zwetend de finish.$$, 'inline'),
  ('0c69403e-2e54-40f8-9526-1620e80db4cb', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$stijgende lichaamstemperatuur en hartslag$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context8.png$$,
   $$Mede doordat Brandons lichaamstemperatuur tijdens het hardlopen steeds hoger werd, ging zijn hart steeds sneller kloppen. Afbeelding 4 geeft dit proces vereenvoudigd weer. Op drie plaatsen in dit schema (bij 1, 2 en 3) moet nog een keuze worden gemaakt.$$, 'inline'),
  ('65d4db2a-5032-4086-9200-6fc24041a0a8', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$afbeelding 4: schema met keuzes bij 1, 2 en 3$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context9.png$$,
   $$afbeelding 4: schema: de lichaamstemperatuur stijgt → de norm voor lichaamstemperatuur (1) gaat omhoog / wordt overschreden → de diameter van slagadertjes in zijn huid wordt (2) groter / kleiner → de bloeddruk (3) stijgt / daalt → de hartslagfrequentie stijgt.$$, 'inline'),
  ('27b3ec58-bdb2-4059-9420-88595a15dd3d', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$kader: voorkoelen met waterijs en boezemfibrilleren$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context10.png$$,
   $$Brandon weet dat zijn prestatie minder wordt als zijn lichaamstemperatuur te ver oploopt. Om het moment waarop oververhitting optreedt uit te stellen, doen sommige sporters aan ‘voorkoelen’: ze eten voor de start van een wedstrijd een liter geschaafd waterijs. Terwijl het ijs smelt in de mond, wordt warmte aan het lichaam onttrokken. Daardoor daalt de lichaamstemperatuur met ongeveer een halve graad. Er zijn mensen die na het eten van een liter geschaafd ijs korte tijd last krijgen van een hartritmestoornis. De koude vloeistof in de slokdarm veroorzaakt afkoeling van een deel van het hart en daarmee wordt de elektrische geleiding van de boezems beïnvloed. De impulsgeleiding verloopt dan chaotisch en ongecontroleerd, waardoor de boezems niet meer effectief samentrekken (boezemfibrilleren). De kamers trekken bij boezemfibrilleren nog wel gecoördineerd samen.$$, 'inline'),
  ('7ca3d019-d423-46e2-b088-3ccaa40a0c31', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$daling van de bloeddruk bij boezemfibrilleren$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context11.png$$,
   $$Een symptoom van boezemfibrilleren is een daling van de bloeddruk.$$, 'inline'),
  ('fa371196-e597-4745-ab77-c3f3425cc472', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$ecg tijdens rustig lopen$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context12.png$$,
   $$Op de universiteit experimenteert Brandon op een loopband met voorkoelen terwijl zijn hartcyclus wordt gemonitord. Hij volgt zijn ecg (elektrocardiogram) op een monitor terwijl hij rustig loopt (afbeelding 5).$$, 'inline'),
  ('1bdcc1b2-b3c7-463d-8116-f55d83984782', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$afbeelding 5: ecg met activatie boezems en kamers$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context13.png$$,
   $$afbeelding 5: normaal ecg met regelmatige pieken; aangegeven zijn de activatie van de boezems (kleine golf) en de activatie van de kamers (hoge piek).$$, 'inline'),
  ('9c9cf29a-be1a-4d57-b4f9-29104875e1af', 'a2925664-3bc4-4015-ade9-ea8973e17c91', $$groter slagvolume, langere kamerdiastole; drie beweringen$$,
   $$biologie-havo-2022-iii-ijskoud-de-beste-context14.png$$,
   $$Brandon is goed getraind: zijn hart heeft daardoor een groter slagvolume gekregen. Hierdoor is de periode dat de kamers ontspannen zijn (kamerdiastole) langer. Dit leidt tot een betere doorbloeding van de hartspier. Drie beweringen over het hart zijn:
1 Bij een langere kamerdiastole is er een lagere hartslagfrequentie in rust.
2 Bij een langere kamerdiastole staan de slagaderkleppen langer open.
3 Door de betere doorbloeding van de hartspier krijgt de hartspier meer zuurstof.$$, 'inline'),
  ('463458f2-0336-4f37-9538-f8e4fdcc2b15', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$inleiding: de Mangrove in Burgers' Zoo (afbeelding 1)$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context1.png$$,
   $$In 2017 werd in Burgers'' Zoo in Arnhem de Mangrove geopend (afbeelding 1). De hal is gemaakt naar voorbeeld van de mangrovebossen in Belize in Midden-Amerika. Willeke Huizinga monitort de biotische en abiotische factoren in deze hal.
afbeelding 1: foto van de overdekte mangrovehal$$, 'inline'),
  ('3b61e10d-d0d4-4c6c-bb12-ea7ad44575af', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$mangrovebossen met steltwortels (afbeelding 2)$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context2.png$$,
   $$Mangrovebossen komen voor aan tropische kusten op plaatsen waar weinig golfslag is. Veel bomen hebben er kenmerkende steltwortels (afbeelding 2), waartussen fijn slib uit rivieren kan bezinken.
De bomen in Burgers'' Mangrove groeien op een moddervlakte die tweemaal per etmaal overspoeld raakt met kunstmatig zeewater.
afbeelding 2: foto van mangrovebomen met steltwortels in het water$$, 'inline'),
  ('de748e44-9d60-459a-8748-0f2234351553', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$selectief ionentransport: door of tussen de wortelcellen$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context3.png$$,
   $$Om zich te beschermen tegen het zoute zeewater nemen mangrovebomen ionen op door selectief transport. Transport van ionen uit de bodem naar het transportweefsel in de wortels van planten kan op twee manieren plaatsvinden:
1 door de wortelcellen heen
2 tussen de wortelcellen door$$, 'inline'),
  ('5ea48ff6-a549-42fd-972d-850528fc4da7', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$ademwortels van mangrovebomen$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context4.png$$,
   $$Sommige soorten mangrovebomen hebben ademwortels (afbeelding 3); dit zijn delen die vanuit de wortels omhoog groeien en boven de bodem uitsteken.$$, 'inline'),
  ('3ee61596-9704-427c-a70d-540732e5a394', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$afbeelding 3: ademwortels; een gasvormige stof voor ondergrondse delen$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context5.png$$,
   $$afbeelding 3: foto van ademwortels die uit een modderbodem omhoog steken
Dankzij de ademwortels kunnen mangrovebomen voldoende opnemen van een gasvormige stof die in ondergrondse delen van de plant nodig is.$$, 'inline'),
  ('2142f6a0-4f17-4e09-94b8-9a7ff88fec15', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$mangrovekwallen en degenkrabben$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context6.png$$,
   $$In het zoute water in de Arnhemse mangrovehal leven mangrovekwallen (afbeelding 4) en degenkrabben (afbeelding 5).$$, 'inline'),
  ('914d81d7-c1f5-47dd-8647-311b6c7af833', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$afbeelding 4 en 5; mutualisme van kwal en algen en troebel water door degenkrabben$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context7.png$$,
   $$afbeelding 4: foto van een mangrovekwal
afbeelding 5: foto van een degenkrab
Mangrovekwallen, die ondersteboven op de modderbodem liggen, hebben een mutualistische relatie met bepaalde algen. De algen leven beschermd in de tentakels van de kwal en geven organische stoffen af die de mangrovekwal nodig heeft.
Degenkrabben woelen de bodem om bij het zoeken naar voedsel. Daardoor wordt het water minder helder. Als gevolg hiervan neemt een bepaalde abiotische factor af, waardoor de mangrovekwallen moeilijker kunnen overleven.$$, 'inline'),
  ('a41b8f59-8995-4bff-925c-2f28f84a4bd2', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$kader: nitraat- en fosfaatnormen in het zoetwaterbassin (afbeelding 6)$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context8.png$$,
   $$In de mangrovehal is ook een groot zoetwaterbassin aangelegd. Daarin leven zeekoeien, schildpadden en vissoorten als cichliden en zwaarddragers.
Willeke laat regelmatig de concentraties nitraat en fosfaat van het water controleren. De waterkwaliteit is in gevaar als de concentratie nitraat hoger wordt dan de norm van 20 mg/L of de concentratie fosfaat hoger wordt dan de norm van 4,0 mg/L.
In afbeelding 6 is het resultaat weergegeven van de metingen in de eerste maanden na het inrichten van het bassin.
afbeelding 6: nitraatconcentratie (mg/L, linker as 0-20, doorgetrokken lijn) en fosfaatconcentratie (mg/L, rechter as 0-8,0, stippellijn) tegen de datum van meting (15 juni 2017 tot 15 januari 2018). Nitraat: ongeveer 4,5 in juni, ongeveer 5 op 15 oktober, 6 op 15 november, ongeveer 9,7 op 15 januari. Fosfaat: ongeveer 0,1 in juni, ongeveer 0,3 op 15 oktober, ongeveer 0,8 op 15 november, ongeveer 2,0 op 15 januari.$$, 'inline'),
  ('bb43f8c9-932d-49c6-ace2-77e4a46a76b3', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$voorspellen wanneer de norm wordt overschreden$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context9.png$$,
   $$De meetresultaten kunnen gebruikt worden om te voorspellen wanneer de waterkwaliteit in gevaar komt. In de uitwerkbijlage zijn de resultaten nog eens weergegeven. Als de toename vanaf december lineair verloopt, zal op een bepaalde datum de concentratie van een van deze stoffen de norm overschrijden.$$, 'inline'),
  ('84a07da3-3dd9-4eff-9c9a-4efd6e297fae', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$te voedselrijk water en algenbloei$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context10.png$$,
   $$Als de concentraties fosfaat en nitraat blijven toenemen, wordt het water te voedselrijk, waardoor algenbloei kan ontstaan.$$, 'inline'),
  ('721c1aee-57f0-4e77-8d64-6af98c9e4559', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$filtersysteem met vier typen bacteriën$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context11.png$$,
   $$Om het probleem van een te hoge concentratie aan mineralen in het water aan te pakken, gebruikt Willeke een filtersysteem met bacteriën. Vier typen bacteriën zijn:
1 denitrificerende bacteriën
2 nitraatbacteriën
3 rottingsbacteriën
4 stikstofbindende bacteriën$$, 'inline'),
  ('178519c1-b90e-43bc-8dab-e6b1ff31d8ce', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$kader: populaties cichliden en zwaarddragers reguleren (afbeelding 7 en 8)$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context12.png$$,
   $$In het bassin groeien de populaties van vissoorten zoals de parelmoercichlide (afbeelding 7) en de groene zwaarddrager (afbeelding 8) erg hard. Daarom overweegt Willeke maatregelen te nemen om de populaties te reguleren.
afbeelding 7: foto van een parelmoercichlide
afbeelding 8: foto van een groene zwaarddrager
Een mogelijke maatregel is het wegvangen van een deel van deze populaties met behulp van grote netten. Willeke wil de regulatie liever op een natuurlijke manier laten plaatsvinden door een predator te introduceren die op zwaarddragers en cichliden jaagt.$$, 'inline'),
  ('8abb3e8f-b7ed-4fcd-afc3-9116bb8c8adf', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$selectie door een predator versus netten$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context13.png$$,
   $$Bij regulatie met behulp van een predator vindt selectie plaats op andere eigenschappen dan bij regulatie met behulp van netten.$$, 'inline'),
  ('b0e2a6d1-0c12-4dca-a344-d56b3d675e97', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$problemen door het introduceren van een predator$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context14.png$$,
   $$Het introduceren van een predator kan ook problemen veroorzaken in het ecosysteem in het bassin.$$, 'inline'),
  ('0e077bf5-1477-4e62-881e-70b4f19b0cb9', '5afd4179-7b14-4955-84fd-d9f87deb4fba', $$uitwerkbijlage bij vraag 12: grafiek nitraat- en fosfaatconcentratie$$,
   $$biologie-havo-2022-iii-mangrove-in-arnhem-context15.png$$,
   $$uitwerkbijlage bij vraag 12: dezelfde grafiek als afbeelding 6 (nitraatconcentratie linker as 0-20 mg/L, fosfaatconcentratie rechter as 0-8,0 mg/L), met een x-as die doorloopt tot 15 mei 2018; de metingen lopen tot 15 januari 2018.$$, 'uitwerkbijlage'),
  ('ec9dbc66-7781-4576-9fa3-e60a9027ad77', '8f966b3e-cde2-4076-954a-713bb0ce1114', $$inleiding: Jimmy is bijziend$$,
   $$biologie-havo-2022-iii-bijziendheid-een-groeiend-probleem-context1.png$$,
   $$Jimmy is negen jaar en draagt een bril om in de verte scherp te kunnen zien. Omdat zijn bijziendheid de afgelopen tijd snel is toegenomen gaat hij met zijn ouders naar Caroline Klaver, oogarts in het Erasmus Medisch Centrum. Klaver doet onderzoek naar de rol van genen en van de omgeving bij het ontstaan van bijziendheid.$$, 'inline'),
  ('abc51720-fbfc-4629-b015-ece220664cb9', '8f966b3e-cde2-4076-954a-713bb0ce1114', $$lezen en tabletgebruik: inspanning om scherp te stellen$$,
   $$biologie-havo-2022-iii-bijziendheid-een-groeiend-probleem-context2.png$$,
   $$Jimmy leest veel en speelt vaak spelletjes op zijn tablet. Zijn ogen moeten zich dan inspannen om het beeld scherp op het netvlies te projecteren.$$, 'inline'),
  ('b08c89c8-a639-4d84-ae63-d5a29a59dd44', '8f966b3e-cde2-4076-954a-713bb0ce1114', $$toegenomen lengte van de oogas (afbeelding 1)$$,
   $$biologie-havo-2022-iii-bijziendheid-een-groeiend-probleem-context3.png$$,
   $$De lengte van de oogas (afbeelding 1) van Jimmy is de laatste jaren toegenomen. Hij is daardoor bijziend.
afbeelding 1: doorsnede van een oog met de oogas aangegeven van hoornvlies tot netvlies$$, 'inline'),
  ('b127aada-cc26-4081-89d8-f47ada3861f5', '8f966b3e-cde2-4076-954a-713bb0ce1114', $$oogdruppels met atropine ontspannen de kringspier van de iris en de spier in het straalvormig lichaam$$,
   $$biologie-havo-2022-iii-bijziendheid-een-groeiend-probleem-context4.png$$,
   $$Jimmy krijgt van oogarts Klaver oogdruppels met atropine voorgeschreven. Door de atropinedruppels ontspannen de kringspier van de iris en de spier in het straalvormig lichaam.$$, 'inline'),
  ('171e64f6-eb6d-4d85-84e4-66d166aad1b7', '8f966b3e-cde2-4076-954a-713bb0ce1114', $$kader: onderzoek met atropine en placebo (afbeelding 2)$$,
   $$biologie-havo-2022-iii-bijziendheid-een-groeiend-probleem-context5.png$$,
   $$Uit onderzoek aan bijziende kinderen is gebleken dat oogdruppels met atropine de ontwikkeling van bijziendheid kunnen afremmen. In dit onderzoek werd gedurende twee jaar bij proefpersonen steeds één van de ogen behandeld met atropine (groep 1) of met een placebo (groep 2). Het andere oog van de proefpersoon werd niet behandeld met atropine of een placebo. De ontwikkeling van de brilsterkte van de behandelde ogen (groep 1a en 2a) en van de niet-behandelde ogen (groep 1b en 2b) werd gemeten (afbeelding 2).
afbeelding 2: gemiddelde brilsterkte (in dioptrieën) bij de 1e meting na behandeling, na 1 jaar en na 2 jaar. Groep 1a (atropine, behandeld oog): ongeveer −2,9; −2,8; −3,1. Groep 1b (atropine, niet-behandeld oog): ongeveer −3,4; −4,2; −4,6. Groep 2a (placebo, behandeld oog): ongeveer −3,6; −4,3; −4,8. Groep 2b (placebo, niet-behandeld oog): ongeveer −3,6; −4,4; −4,8.$$, 'inline'),
  ('5838f396-98c2-4e44-a620-df3b78f4e611', '8f966b3e-cde2-4076-954a-713bb0ce1114', $$het placebo-effect$$,
   $$biologie-havo-2022-iii-bijziendheid-een-groeiend-probleem-context6.png$$,
   $$Mensen die bij een onderzoek een placebo krijgen, merken soms ook een positief effect (het placebo-effect).$$, 'inline'),
  ('1387bd17-8e5e-4de4-9abd-867cf19d4c77', '8f966b3e-cde2-4076-954a-713bb0ce1114', $$een controlegroep om atropine als werkzame stof aan te tonen$$,
   $$biologie-havo-2022-iii-bijziendheid-een-groeiend-probleem-context7.png$$,
   $$Om te kunnen aantonen dat atropine de werkzame stof is in de oogdruppels, was er in het experiment een controlegroep.$$, 'inline'),
  ('d027f650-f0e3-4937-994c-c163ebd2553d', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$inleiding: voetballer doneert stamcellen$$,
   $$biologie-havo-2022-iii-stamceldonatie-context1.png$$,
   $$Voetballer Lennart Thy miste een wedstrijd van zijn club VVV-Venlo tegen PSV omdat hij in het ziekenhuis verbleef voor een stamceldonatie. Na het zien van het nieuwsitem over Lennart Thy overweegt Paul om ook stamceldonor te worden.$$, 'inline'),
  ('094db01b-7de5-4253-9ca4-9271aa9acfe4', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$kader: stamcelbehandeling bij leukemie$$,
   $$biologie-havo-2022-iii-stamceldonatie-context2.png$$,
   $$De gedoneerde stamcellen worden gebruikt voor de behandeling van leukemie. Leukemie is een aandoening waarbij de productie van witte bloedcellen ontregeld is. Voor de stamcelbehandeling bij leukemie worden eerst de beenmergcellen van de patiënt gedood door middel van chemotherapie. Daarna worden gezonde beenmergstamcellen van een geschikte donor bij de patiënt ingebracht.$$, 'inline'),
  ('a4c4ecbb-e14f-423c-b23f-9ec26075bb4f', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$na het doden van de beenmergcellen werkt het afweersysteem niet goed$$,
   $$biologie-havo-2022-iii-stamceldonatie-context3.png$$,
   $$Nadat de beenmergcellen gedood zijn, moet de patiënt in een steriele kamer verblijven en wordt het bezoek beperkt om infecties te voorkomen. Het afweersysteem van de patiënt werkt dan namelijk niet goed.$$, 'inline'),
  ('8cee734e-d84b-4c67-86c1-e4f8f57c82e6', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$drie eigenschappen van lichaamscellen$$,
   $$biologie-havo-2022-iii-stamceldonatie-context4.png$$,
   $$Hieronder staan eigenschappen die een lichaamscel kan hebben.
1 bevat mitochondriën
2 kan zich differentiëren
3 produceert eiwitten$$, 'inline'),
  ('aa67338c-3b9c-4a4f-9859-a099419fa8bd', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$kader: aanmelden als donor met wangslijmvlies$$,
   $$biologie-havo-2022-iii-stamceldonatie-context5.png$$,
   $$Paul meldt zich aan als stamceldonor. Hij krijgt een steriel wattenstaafje thuisgestuurd waarmee hij wat wangslijmvlies verzamelt. Als hij dit heeft teruggestuurd voor DNA-onderzoek, hoeft Paul voorlopig niets meer te doen. Hij zal worden opgeroepen als zijn stamcellen nodig zijn.$$, 'inline'),
  ('51136ed8-c9fb-49d9-8759-e6220660726c', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$kader: HLA-eiwitten en zes HLA-genen op chromosoom 6$$,
   $$biologie-havo-2022-iii-stamceldonatie-context6.png$$,
   $$Paul is geschikt als stamceldonor als de HLA-eiwitten op zijn cellen voldoende overeenkomen met die van de ontvangende patiënt. HLA- eiwitten zijn aanwezig op bijna alle lichaamscellen. Deze eiwitten zorgen ervoor dat het afweersysteem de lichaamscellen als lichaamseigen herkent. Op chromosoom 6 liggen zes genen dicht bij elkaar, die elk voor een verschillend HLA-eiwit coderen. Van elk HLA-gen zijn vele allelen bekend. Alle allelen van deze zes genen die bij iemand aanwezig zijn, komen in gelijke mate tot expressie. Hierdoor is de kans heel klein dat twee niet-verwante personen dezelfde HLA-eiwitten hebben.$$, 'inline'),
  ('b8a2373d-9a22-4b9d-b962-965cb6a25ddd', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$drie uitspraken over HLA-genen$$,
   $$biologie-havo-2022-iii-stamceldonatie-context7.png$$,
   $$Over HLA-genen worden drie uitspraken gedaan:
1 Er zijn multipele allelen voor elk HLA-gen.
2 Bij elk HLA-gen is een van de allelen dominant.
3 De HLA-genen erven gekoppeld over.$$, 'inline'),
  ('9221fd47-9af8-4fab-b21c-e738db7b16c9', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$vergelijken van HLA-allelen voor een ideale match$$,
   $$biologie-havo-2022-iii-stamceldonatie-context8.png$$,
   $$Met het wangslijmvliesmonster wordt bepaald welke allelen Paul heeft van de zes HLA-genen. Deze allelen worden vergeleken met de HLA-allelen van patiënten uit de database. Om stamcellen te kunnen doneren moet er een match zijn tussen de stamceldonor en de ontvangende patiënt. Bij een ideale match zijn alle allelen hetzelfde.$$, 'inline'),
  ('725aa8fb-c5b3-4214-8987-2e71c1b7298a', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$beenmergpunctie, minder rode bloedcellen en duizeligheid$$,
   $$biologie-havo-2022-iii-stamceldonatie-context9.png$$,
   $$Twee maanden nadat Paul zijn wattenstaafje heeft opgestuurd, wordt hij opgeroepen om stamcellen te doneren. Een manier om stamcellen af te nemen is een beenmergpunctie. Na de beenmergpunctie is de productie van rode bloedcellen bij de donor tijdelijk iets verlaagd, waardoor klachten als vermoeidheid en duizeligheid kunnen ontstaan. De duizeligheid is een verschijnsel dat zich afspeelt op organisme-niveau en kan worden verklaard door processen die zich afspelen op lagere organisatieniveaus. Dit is schematisch weergegeven in afbeelding 1. Dit schema is nog niet compleet.$$, 'inline'),
  ('98ff9a0e-d1fb-48f3-bb60-d15df81e2c61', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$afbeelding 1: schema met organisatieniveaus en vakjes 1 tot en met 4$$,
   $$biologie-havo-2022-iii-stamceldonatie-context10.png$$,
   $$afbeelding 1: schema met de organisatieniveaus organisme-niveau, orgaanniveau, weefselniveau, celniveau, organelniveau en molecuulniveau. Op weefselniveau: beenmergpunctie → minder celdelingen → vakje 1; daarna pijl naar vakje 2 (organelniveau) → vakje 3 (celniveau) → vakje 4 (orgaanniveau) → duizeligheid (organisme-niveau).$$, 'inline'),
  ('0a2fbd32-b153-4c46-ad13-79f18a1b3eec', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$processen P, Q, R en S voor het schema$$,
   $$biologie-havo-2022-iii-stamceldonatie-context11.png$$,
   $$De volgende processen moeten nog in dit schema worden ingevuld:
P verlaagde aerobe dissimilatie die leidt tot verminderde ATP-productie
Q het bloed transporteert minder zuurstof
R verstoorde communicatie tussen hersengebieden
S verstoorde impulsgeleiding$$, 'inline'),
  ('bb4eeeb1-9c64-48dc-b498-0968b8e61571', '2e6c265b-a7aa-431e-8b00-8c8e7954e87b', $$de groeifactor G-CSF$$,
   $$biologie-havo-2022-iii-stamceldonatie-context12.png$$,
   $$Bij Paul wordt een andere methode toegepast om stamcellen te verkrijgen. Hij krijgt via een injectie een groeifactor (G-CSF) toegediend die de stamcellen in het beenmerg stimuleert om te gaan delen. Ook stimuleert G-CSF de migratie van stamcellen naar de bloedbaan. Daardoor kunnen na vijf dagen stamcellen worden verkregen uit zijn bloed. De werking van G-CSF komt overeen met de werking van een bepaalde groep stoffen.$$, 'inline'),
  ('8fc80781-f62a-411e-80d7-f42567f6331e', '077cf99c-5be1-4e29-b2f6-d58aaa51e201', $$inleiding: bemesting en regenwormen als voedsel voor de kievit$$,
   $$biologie-havo-2022-iii-regenwormen-voor-vogels-en-planten-context1.png$$,
   $$Jeroen Onrust van de Rijksuniversiteit Groningen heeft onderzocht wat de invloed van de bemesting van grasland is op de beschikbaarheid van regenwormen voor weidevogels zoals de kievit.$$, 'inline'),
  ('333fc466-375f-4950-81a9-ecc579e6e70a', '077cf99c-5be1-4e29-b2f6-d58aaa51e201', $$kader: detrivoren en geofagen, stalmest en drijfmest (onderzoek 1)$$,
   $$biologie-havo-2022-iii-regenwormen-voor-vogels-en-planten-context2.png$$,
   $$In Nederlandse graslanden leven verschillende soorten regenwormen. Regenwormen (afbeelding 1) zijn te verdelen in twee ecologische groepen: detrivoren en geofagen. Detrivoren leven van grof plantaardig materiaal. Geofagen leven van fijner verdeeld organisch materiaal en van bodembacteriën.
afbeelding 1: foto van regenwormen op grond
In de afgelopen decennia is de landbouw steeds intensiever geworden. Daarmee is ook de manier van bemesten veranderd. In plaats van het strooien van stalmest (uitwerpselen met stro) op het gras, wordt tegenwoordig drijfmest (uitwerpselen vermengd met urine) geïnjecteerd in de bodem. Deze verandering heeft effect gehad op de regenwormensamenstelling in de bodem.
Jeroen Onrust bepaalde het aantal regenwormen per m² grasland door steekproefsgewijs het aantal regenwormen in een graszode van 20 x 20 x 20 cm te tellen (onderzoek 1). Hij deed dit voor graslanden bemest met drijfmest, graslanden bemest met stalmest en graslanden bemest met een mengsel van drijfmest en stalmest.$$, 'inline'),
  ('fb977da8-db4f-4965-adf2-b7ef1e2a408f', '077cf99c-5be1-4e29-b2f6-d58aaa51e201', $$detrivoren en geofagen als aparte balkjes$$,
   $$biologie-havo-2022-iii-regenwormen-voor-vogels-en-planten-context3.png$$,
   $$De resultaten van het onderzoek staan in afbeelding 2. De detrivoren en geofagen zijn als aparte balkjes weergegeven.$$, 'inline'),
  ('cb32b39a-be4d-4b83-a4d8-cb7f1892f902', '077cf99c-5be1-4e29-b2f6-d58aaa51e201', $$afbeelding 2: aantal regenwormen per m² per type bemesting$$,
   $$biologie-havo-2022-iii-regenwormen-voor-vogels-en-planten-context4.png$$,
   $$afbeelding 2: staafdiagram van het aantal regenwormen per m² grasland, met voor elk type bemesting een balk P en een balk Q. Drijfmest: P ongeveer 70, Q ongeveer 310. Stalmest: P ongeveer 220, Q ongeveer 320. Drijfmest + stalmest: P ongeveer 100, Q ongeveer 270.$$, 'inline'),
  ('777ae9a2-ebef-4744-9e91-b9553b9a34fe', '077cf99c-5be1-4e29-b2f6-d58aaa51e201', $$kader: tellen van zichtbare regenwormen vanaf een kar (onderzoek 2, afbeelding 3)$$,
   $$biologie-havo-2022-iii-regenwormen-voor-vogels-en-planten-context5.png$$,
   $$Jeroen Onrust was ook benieuwd hoeveel regenwormen er in het grasland beschikbaar zijn als voedsel voor de kievit. Kieviten vangen alleen regenwormen die voor hen zichtbaar zijn. Om deze beschikbaarheid te meten ontwierp Onrust een kar (afbeelding 3) waarmee hij over het grasland kon rijden om de regenwormen tussen het gras te tellen, zonder daarbij trillingen te veroorzaken die het gedrag van de regenwormen beïnvloeden (onderzoek 2). Op deze manier onderzocht hij meerdere stroken op verschillende typen grasland.
afbeelding 3: tekening en foto van een onderzoeker die liggend op een kar met wielen over het gras rijdt$$, 'inline'),
  ('868a9455-f1e1-4c86-bd32-536cb5adc870', '077cf99c-5be1-4e29-b2f6-d58aaa51e201', $$tellen vanaf de kar en meerdere stroken maakten het onderzoek beter$$,
   $$biologie-havo-2022-iii-regenwormen-voor-vogels-en-planten-context6.png$$,
   $$Door te tellen vanaf de kar in plaats van kruipend door het gras én doordat Onrust per grasland meerdere stroken bekeek, werd het onderzoek beter.$$, 'inline'),
  ('423a7087-5629-4bcb-8628-940216d30054', '077cf99c-5be1-4e29-b2f6-d58aaa51e201', $$kader: tabel 1 met resultaten per bodemtype en type grasland$$,
   $$biologie-havo-2022-iii-regenwormen-voor-vogels-en-planten-context7.png$$,
   $$Een gedeelte van de resultaten uit onderzoek 1 en onderzoek 2 staat in tabel 1 weergegeven. De gegevens zijn uitgesplitst naar bodemtype: kleigrond of veengrond, en naar type grasland: soortenrijk of monocultuur (voornamelijk één soort gras).
tabel 1 (bodemtype / type grasland / onderzoek 1: aantal regenwormen per m² / onderzoek 2: aantal zichtbare regenwormen per m²):
kleigrond / soortenrijk / 264 / 1,22
kleigrond / monocultuur / 354 / 1,10
veengrond / soortenrijk / 371 / 0,44
veengrond / monocultuur / 543 / 1,76$$, 'inline'),
  ('c302bfb7-cf20-4df8-aa80-f4774019d60d', '077cf99c-5be1-4e29-b2f6-d58aaa51e201', $$drie uitspraken over tabel 1$$,
   $$biologie-havo-2022-iii-regenwormen-voor-vogels-en-planten-context8.png$$,
   $$Naar aanleiding van de resultaten in tabel 1 worden drie uitspraken gedaan.
1 Bij beide bodemtypen zijn bij soortenrijk grasland meer regenwormen beschikbaar voor kieviten dan bij monocultuur-grasland.
2 Bij soortenrijk grasland op kleigrond is gemiddeld een groter gedeelte van de regenwormen zichtbaar dan bij soortenrijk grasland op veengrond.
3 Het aantal regenwormen per m² (in onderzoek 1) is een bruikbare maat voor de beschikbaarheid van regenwormen voor kieviten.$$, 'inline'),
  ('ad77b0e3-3cc9-4e3f-8a45-9f9dd9d641e8', '077cf99c-5be1-4e29-b2f6-d58aaa51e201', $$berekening van het aantal kieviten per 10.000 m²$$,
   $$biologie-havo-2022-iii-regenwormen-voor-vogels-en-planten-context9.png$$,
   $$Jeroen Onrust berekende dat een volwassen kievit per dag 555 regenwormen nodig heeft om te voldoen aan zijn energiebehoefte. Met behulp van de resultaten van onderzoek 2 (tabel 1) is te berekenen dat er 7,9 kieviten kunnen leven per 10.000 m² soortenrijke veengrond.$$, 'inline'),
  ('d2be75a8-ca38-43df-9710-c2a2e141b7bd', '077cf99c-5be1-4e29-b2f6-d58aaa51e201', $$geofagen maken fosfor beschikbaar; vier organische stoffen$$,
   $$biologie-havo-2022-iii-regenwormen-voor-vogels-en-planten-context10.png$$,
   $$De geofagen eten bodemdeeltjes. In het spijsverteringskanaal van deze regenwormen komt fosfaat los van de bodemdeeltjes. Hierdoor komt het element fosfor (P) in de uitwerpselen van regenwormen beschikbaar voor planten. Vier organische stoffen in planten zijn:
1 ATP
2 DNA
3 eiwit
4 fosfolipiden$$, 'inline'),
  ('7bd88aec-d532-4547-bd85-c16a0e3aba5d', '077cf99c-5be1-4e29-b2f6-d58aaa51e201', $$regenwormen en het versterkt broeikaseffect$$,
   $$biologie-havo-2022-iii-regenwormen-voor-vogels-en-planten-context11.png$$,
   $$Over het effect van regenwormen op het versterkt broeikaseffect is veel discussie. Aan de ene kant dragen regenwormen bij aan het versterkt broeikaseffect doordat ze broeikasgassen uitstoten. Aan de andere kant kunnen ze het versterkt broeikaseffect tegengaan omdat ze de bodemstructuur verbeteren en de fosfaatbeschikbaarheid verhogen.$$, 'inline'),
  ('94dca42b-8b15-4e7a-acf3-b6a067832704', '0fc2ea89-260b-459f-9a29-d5ebcc4f6327', $$inleiding: Tessa's milt is verwijderd$$,
   $$biologie-havo-2022-iii-leven-zonder-milt-context1.png$$,
   $$Tessa is drie jaar geleden van haar paard gevallen. Als gevolg van deze val moest haar milt worden verwijderd.$$, 'inline'),
  ('2c1ddd28-a100-4c9a-a883-95e4991e5a96', '0fc2ea89-260b-459f-9a29-d5ebcc4f6327', $$kader: bouw van de milt met gesloten en open circulatie (afbeelding 1)$$,
   $$biologie-havo-2022-iii-leven-zonder-milt-context2.png$$,
   $$Tessa werd na haar val in kritieke toestand naar het ziekenhuis gebracht. Daar bleek dat haar milt was gescheurd. Om het bloedverlies te stoppen, werd Tessa''s milt onmiddellijk verwijderd via een snede in de buik.
De milt is een bloedrijk orgaan. Een deel van het bloed dat de milt inkomt, stroomt via slagadertjes naar brede bloedruimten – de sinussen – die uitmonden in een ader. Deze route is de gesloten circulatie (afbeelding 1). Een ander deel van het bloed stroomt uit slagadertjes tussen de cellen van de rode pulpa en dringt vervolgens via de wanden de sinussen binnen. Bij deze route (de open circulatie) wordt het bloed gefilterd: verouderde bloeddeeltjes blijven achter in de rode pulpa en worden daar afgebroken.
Rondom de slagadertjes bevindt zich de witte pulpa met daarin veel witte bloedcellen.
afbeelding 1: doorsnede van een deel van de milt met rode pulpa, ader, witte pulpa, sinus en slagadertje; de gesloten en de open circulatie zijn omcirkeld.$$, 'inline'),
  ('1553fc0c-a9f6-4bd7-bbbd-767aca7b71a4', '0fc2ea89-260b-459f-9a29-d5ebcc4f6327', $$afbraak van rode bloedcellen door andere organen$$,
   $$biologie-havo-2022-iii-leven-zonder-milt-context3.png$$,
   $$Vroeger werd gedacht dat de milt niet zo’n belangrijk orgaan was, omdat veel functies van de milt – zoals de afbraak van rode bloedcellen – ook door andere organen kunnen worden overgenomen.$$, 'inline'),
  ('ccb323b4-99ac-465c-ab82-a21c5997b467', '0fc2ea89-260b-459f-9a29-d5ebcc4f6327', $$bloedverdunner: minder afbraak van bloeddeeltjes die bloedstolling in gang zetten$$,
   $$biologie-havo-2022-iii-leven-zonder-milt-context4.png$$,
   $$Na de operatie kreeg Tessa tijdelijk een bloedverdunner (antistollingsmiddel) voorgeschreven, omdat er een vergrote kans was op het ontstaan van bloedstolseltjes. Als de milt ontbreekt, is er namelijk minder afbraak van bloeddeeltjes die bloedstolling in gang zetten.$$, 'inline'),
  ('ceb41e89-c647-4818-9fdd-89d87eb53cb4', '0fc2ea89-260b-459f-9a29-d5ebcc4f6327', $$kader: wand van een sinus (afbeelding 2a en 2b)$$,
   $$biologie-havo-2022-iii-leven-zonder-milt-context5.png$$,
   $$In de open circulatie van de milt worden oude rode bloedcellen verwijderd dankzij de speciale bouw van de sinussen. In afbeelding 2 is de wand van een sinus schematisch weergegeven.
afbeelding 2a: sinuswand opgebouwd uit langwerpige endotheelcellen met ringvormige vezels eromheen; rode bloedcellen persen zich door smalle spleten tussen de endotheelcellen de sinus in (pijlen: richting verplaatsing rode bloedcellen).
afbeelding 2b: vergroting van endotheelcellen met stress-vezels.$$, 'inline'),
  ('94415e63-80de-4c12-877c-1c6b7f7e71f5', '0fc2ea89-260b-459f-9a29-d5ebcc4f6327', $$stugger celmembraan van oude rode bloedcellen$$,
   $$biologie-havo-2022-iii-leven-zonder-milt-context6.png$$,
   $$Naarmate rode bloedcellen ouder worden, wordt hun celmembraan stugger.$$, 'inline'),
  ('7fdeb1e9-99ca-4c13-a372-3aca40065bc1', '0fc2ea89-260b-459f-9a29-d5ebcc4f6327', $$stress-vezels in endotheelcellen tijdens inspanning$$,
   $$biologie-havo-2022-iii-leven-zonder-milt-context7.png$$,
   $$De sinussen zijn een reservoir voor rode bloedcellen. De endotheelcellen van de sinussen bevatten speciale stress-vezels (afbeelding 2b). Tijdens inspanning trekken deze stress-vezels samen, waardoor zo’n 150 mL aan rode bloedcellen extra aan de bloedsomloop kan worden toegevoegd.$$, 'inline'),
  ('39432715-e226-4b79-9630-f45b2b33e907', '0fc2ea89-260b-459f-9a29-d5ebcc4f6327', $$kader: stoornis in de afweer en vaccinatie$$,
   $$biologie-havo-2022-iii-leven-zonder-milt-context8.png$$,
   $$Als de milt is verwijderd, ontstaat er een stoornis in de afweer. Besmetting met bepaalde bacteriën zoals Streptococcus pneumoniae kan dan leiden tot een levensbedreigende infectie. Om zo’n infectie te voorkomen, kreeg Tessa twee weken na de operatie een vaccinatie tegen een aantal soorten bacteriën.$$, 'inline'),
  ('6f1bab6e-f675-47af-b42a-97577e0a1b15', '0fc2ea89-260b-459f-9a29-d5ebcc4f6327', $$koorts: verhoogde normwaarde in de hypothalamus; drie symptomen$$,
   $$biologie-havo-2022-iii-leven-zonder-milt-context9.png$$,
   $$Een infectie met bacteriën leidt tot een verhoging van de normwaarde voor lichaamstemperatuur in de hypothalamus (tot bijvoorbeeld
40 °C). Hierdoor ontstaat koorts: de lichaamstemperatuur zal oplopen tot boven de 38 °C. Als Tessa koorts krijgt, moet ze meteen antibiotica nemen. Daarom is ze alert op de symptomen van koorts. Mogelijke symptomen bij Tessa zijn:
1 Ze gaat rillen.
2 Ze gaat zweten.
3 Ze heeft het warm.$$, 'inline'),
  ('62176ef3-e577-4c5d-8fe7-aa3b2057d4ff', '6825a09c-77b4-41ca-b8d9-ba3b0005636f', $$inleiding: essentaksterfte bedreigt de es$$,
   $$biologie-havo-2022-iii-essentaksterfte-context1.png$$,
   $$De es, een in Nederland algemeen voorkomende boom, dreigt door de ziekte ‘essentaksterfte’ uit het landschap te verdwijnen. Boomdeskundige Melany rijdt regelmatig langs de essen in haar regio om te inspecteren welke bomen aangetast zijn. Ze herkent deze bomen aan verdorde bladeren en dode takken.$$, 'inline'),
  ('d5fb53e6-c605-4507-8e16-dd04e946b4a4', '6825a09c-77b4-41ca-b8d9-ba3b0005636f', $$kader: aantasting door het vals essenvlieskelkje (afbeelding 1 en 2)$$,
   $$biologie-havo-2022-iii-essentaksterfte-context2.png$$,
   $$afbeelding 1: foto van een es in het landschap
afbeelding 2: foto van verdorde essenbladeren
De zieke essen (Fraxinus excelsior, afbeelding 1) zijn aangetast door de schimmel vals essenvlieskelkje (Hymenoscyphus fraxineus). Sporen van deze schimmel blijven plakken op essenbladeren. De ontkiemende spore geeft een stof af die de opperhuid van het blad beschadigt. Daarna groeien schimmeldraden de weefsels van het blad in. De schimmel groeit verder via het transportweefsel naar de takken en de stam. Hierdoor raken vaten verstopt. Een direct gevolg hiervan is dat bladeren verwelken (slap gaan hangen) en uiteindelijk verdorren (afbeelding 2).$$, 'inline'),
  ('fa1ccf53-ef15-487a-9032-505537cdffed', '6825a09c-77b4-41ca-b8d9-ba3b0005636f', $$schimmeldraden in het transportweefsel$$,
   $$biologie-havo-2022-iii-essentaksterfte-context3.png$$,
   $$Bij een zieke es worden schimmeldraden in het transportweefsel aangetroffen. Afbeelding 3 toont een dwarsdoorsnede van een tak.$$, 'inline'),
  ('4c6522e3-5424-4a33-b46d-6594fce27b6d', '6825a09c-77b4-41ca-b8d9-ba3b0005636f', $$afbeelding 3: dwarsdoorsnede van een tak met letters P tot en met T$$,
   $$biologie-havo-2022-iii-essentaksterfte-context4.png$$,
   $$afbeelding 3: microscopische dwarsdoorsnede van een tak, van buiten (boven) naar binnen (onder); de letters P, Q, R, S en T wijzen achtereenvolgens naar weefsellagen van de buitenkant naar het midden van de tak.$$, 'inline'),
  ('3843b535-f431-4479-89ec-ceb87114f2e5', '6825a09c-77b4-41ca-b8d9-ba3b0005636f', $$cellen zonder bladgroenkorrels maar met celkern en celwand$$,
   $$biologie-havo-2022-iii-essentaksterfte-context5.png$$,
   $$Melany bekijkt een aantal preparaten van bladmateriaal met een microscoop. In een preparaat ziet ze cellen zonder bladgroenkorrels, maar met een celkern en een celwand. Cellen in het preparaat zouden afkomstig kunnen zijn van:
1 de schimmel
2 de es
3 een bladluis$$, 'inline'),
  ('fbf2f7d7-3d85-4579-969f-0075e240b560', '6825a09c-77b4-41ca-b8d9-ba3b0005636f', $$de schimmel leeft van organische stoffen van de es$$,
   $$biologie-havo-2022-iii-essentaksterfte-context6.png$$,
   $$De schimmel leeft van organische stoffen uit beschadigde cellen van de es.$$, 'inline'),
  ('e756b2e9-e062-4047-a3bd-3fb698fb463f', '6825a09c-77b4-41ca-b8d9-ba3b0005636f', $$kader: waarom niet alle essen preventief worden weggehaald$$,
   $$biologie-havo-2022-iii-essentaksterfte-context7.png$$,
   $$Tijdens haar inspectieronde in een park ziet Melany dat er een grote dode tak van een es boven een wandelpad hangt. Ze laat de boom weghalen. Gezonde essen en aangetaste essen die geen gevaar opleveren, laat ze staan. Een wandelaar vraagt aan Melany waarom niet alle essen in het park preventief weggehaald worden. De volgende zinnen geven het antwoord van Melany gedeeltelijk weer: De ziekte veroorzaakt …(1)… bij de essen. Door de andere essen te laten staan, kan door evolutie een populatie essen ontstaan die …(2)… de ziekte.$$, 'inline'),
  ('b3a0985d-fc2b-4cb2-bb30-21e543b42778', '6825a09c-77b4-41ca-b8d9-ba3b0005636f', $$twee methoden voor een nieuwe populatie gezonde essen$$,
   $$biologie-havo-2022-iii-essentaksterfte-context8.png$$,
   $$Twee methoden om weer een populatie gezonde essen te krijgen, zijn:
1 het ongeslachtelijk vermeerderen van een es die infectie met de schimmel heeft overleefd
2 kweken met de zaden van een groot aantal essen die infectie met de schimmel hebben overleefd Om op de lange termijn een populatie gezonde essen te krijgen is methode 2 een betere keuze dan methode 1.$$, 'inline');

